        'pit-level-sensor-used-for-mud-logging' => ['level_ultrasonic', 'Ultrasonic Pit Level Sensor: Selection & Interface Review', 'Ultrasonic pit level sensor', 'The source describes an ultrasonic fluid-level application. Confirm installation geometry, usable measuring span and output for the exact version; a level signal alone does not establish tank volume.'],
        'cnps-ml11-fluid-level-sensor' => ['level_ultrasonic', 'CNPS-ML11 Fluid Level Sensor: Installation & Compatibility', 'CNPS-ML11 fluid level sensor', 'The original parameter formatting and calibration menu are retained below. Confirm their meaning and applicability with the supplier; do not transfer this menu or specifications to another level transmitter.'],
        'sitrans-probe-lu240-ultrasonic-pit-level-transmitter' => ['level_ultrasonic', 'SITRANS Probe LU240: Pit Level Selection & Technical Manual', 'SITRANS Probe LU240 pit level transmitter', 'Range and interface options depend on the ordered LU240 configuration. The linked Siemens family manual is a reference to check against the actual order code and firmware, not proof of the supplied configuration or approval.'],
        'rada-32-ddlja5-80ghz-radar-level-transmitter' => ['level_radar', 'RADA-32-DDLJA5 Radar Level Transmitter: Configuration Review', 'RADA-32-DDLJA5 radar level transmitter', 'The source combines a named radar model with broader family options. Confirm the complete order code, process connection, materials and protocol; do not combine all family limits or options into one offered unit.'],
        'cnps-dnj-electric-torque-sensor' => ['torque', 'CNPS-DNJ Electric Torque Sensor: Current & Interface Review', 'CNPS-DNJ electric torque sensor', 'This source combines CNPS-DNJ descriptions with a HU-404 parameter section. Supply, output and bandwidth descriptions differ. Confirm the exact offered version; do not combine the sections into one specification.'],
        'cnps-dw-a11-depth-encoder' => ['depth', 'CNPS-DW-A11 Depth Encoder: Pulse Interface & Depth Scaling', 'CNPS-DW-A11 depth encoder', 'The source describes two pulse channels and drawworks shaft motion. Some power/response entries have unclear unit formatting; they are retained for reference, not interpreted as verified limits. Confirm the model-matched datasheet and drawing.'],
        'cnps-mhp-pressure-sensor-15000psi' => ['pressure', 'CNPS-MHP Pressure Sensor: Range & Interface Review', 'CNPS-MHP pressure sensor', 'Unresolved range conflict: the product heading says 15,000 psi, while the original table states 0-2.5 bar and the text lists other ranges. This page does not verify a 15,000 psi rating. Confirm the ordered range and complete pressure connection before selection.'],
        'electric-torque-sensor' => ['torque', 'Electric Torque Sensor: Current Signal & Calibration Review', 'Electric torque sensor', 'This sparse catalogue record describes electrical current sensing but does not establish a model-matched torque conversion, wiring diagram or complete configuration. Do not copy values from another torque catalogue page.'],
        'mud-logging-sensor-named-casing-pressure-sensor' => ['pressure', 'Casing Pressure Sensor: Range, Connection & Interface Selection', 'Casing pressure sensor', 'The original pressure record includes an unrelated Pump Stroke paragraph. That paragraph does not establish pressure-sensor function or compatibility. Confirm the exact pressure transmitter, connection and ordered range.'],
        'mud-logging-sensor-named-standpipe-pressure-sensor' => ['pressure', 'Standpipe Pressure Sensor: Selection & Interface Compatibility', 'Standpipe pressure sensor', 'The original pressure record includes an unrelated Pump Stroke paragraph. Retain it as source text, not as proof of pressure-transmitter performance. Confirm the offered model, pressure connection and interface.'],
        'mud-logging-sensor-of-electric-torque-sensor' => ['torque', 'Mud Logging Electric Torque Sensor: Current-to-Torque Review', 'Mud logging electric torque sensor', 'The source describes Hall-effect current sensing used for rotary-table monitoring. Its current range and output are not a verified mechanical torque range. Confirm the motor/drive conversion and calibration basis separately.'],
        'wireless-casing-pressure-sensor-for-mud-logging-unit' => ['pressure', 'Wireless Casing Pressure Sensor: Selection & Receiver Interface', 'Wireless casing pressure sensor', 'The listed local supply and voltage output do not establish the wireless receiver interface. Confirm this exact pressure range and complete connection assembly; do not substitute a standpipe record solely because it looks similar.'],
        'wireless-electric-torque-sensor-for-mud-logging-unit' => ['torque', 'Wireless Electric Torque Sensor: Current & Receiver Selection', 'Wireless electric torque sensor', 'The source specifies current sensing and local voltage output. Confirm the transmitter/receiver pair and the motor-specific current-to-torque relationship; neither the wireless label nor the current range proves a calibrated torque measurement.'],
        'wireless-standpipe-pressure-sensor-for-mud-logging-unit' => ['pressure', 'Wireless Standpipe Pressure Sensor: Range & System Selection', 'Wireless standpipe pressure sensor', 'The listed local electrical values and pressure range apply to this source record only. Confirm the offered transmitter, pressure connection and receiver output before assessing compatibility with the logging system.'],
        'mud-logging-sensor-named-hookload-sensor' => ['hook', 'Hookload Sensor: Pressure-to-Load & Interface Review', 'Hookload sensor', 'The source describes a pressure transmitter and contains an unrelated Pump Stroke paragraph. Pressure range alone does not establish hookload capacity or accuracy. Confirm the hydraulic conversion, rig arrangement and calibration basis.'],
        'wireless-hook-load-sensor-for-mud-logging-unit' => ['hook', 'Wireless Hook Load Sensor: Scaling & Receiver Compatibility', 'Wireless hook load sensor', 'The source measures hydraulic pressure used for hookload indication. Its accuracy formatting and temperature entry are incomplete; do not infer missing units or an upper limit. Confirm the offered sensor and receiver configuration.'],
        'wireless-hydrogen-sulfide-h2s-sensor-for-mud-logging-unit' => ['gas', 'Wireless H2S Sensor: Selection & Monitoring Interface', 'Wireless H2S sensor', 'The source concentration, response and temperature-condition entries require clarification. A sensor response figure is not a verified end-to-end wireless alarm time. The catalogue does not establish a complete personnel-protection or alarm-system approval.'],
        'wireless-master-station' => ['wireless_master', 'Wireless Master Station: Node, Protocol & Interface Selection', 'Wireless master station', 'The source lists 2 × 25 nodes but later refers to 2k channels, and board supply descriptions differ. Capacity, board signalling and antenna-interface wording need a matched manual; do not combine these descriptions into one verified configuration.'],
        'wireless-sensors-for-mud-logging-unit' => ['wireless_system', 'Wireless Mud Logging Sensors: System & WITS Compatibility', 'Wireless mud logging sensor system', 'Original endurance, communication-distance and installation-time statements are catalogue claims, not verified guarantees for your site. A WITS reference alone does not establish compatibility with every logging application.'],
        'battery-and-charger-used-for-the-transmission-box-of-wireless-sensors' => ['power', 'Wireless Sensor Battery & Charger: Compatibility Selection', 'Wireless sensor battery and charger', 'Confirm the exact pack and designated charger. The source table and charging-process text describe different current values and conditions; they are not a universal charging procedure or proof that this pack fits every wireless node.'],
        'mud-logging-ex-proof-degasser' => ['degasser', 'Mud Logging Degasser: Gas Extraction & Configuration Review', 'Mud logging degasser', 'This source describes CL-DT motor variants and gas collection for logging. Keep their electrical values and markings separate from YC-03D. A motor marking does not independently establish approval of the complete supplied assembly.'],
        'yc-03d-electric-mud-degasser' => ['degasser', 'YC-03D Electric Mud Degasser: Selection & Gas-Line Interface', 'YC-03D electric mud degasser', 'This source describes gas extraction, drying and cleaning before downstream analysis. It does not establish gas-analysis accuracy, extraction efficiency or suitability for an unspecified tubing/process degassing duty. Confirm the exact configuration and documentation.'],
        'mud-logging-oil-fluoroscope-uv-lamp-box' => ['fluoroscope', 'Mud Logging Oil Fluoroscope: UV Box & Sample Selection', 'Mud logging oil fluoroscope UV lamp box', 'The source identifies CNPS-OL1501 and includes visual interpretation and legacy sample-treatment text. These are not independently validated quantitative oil-content results or a current sample-handling procedure. Confirm model-matched operating and safety documents.'],
        'oil-fluoroscope-uv-box' => ['fluoroscope', 'Oil Fluoroscope UV Box: YG1501 Selection & Documentation', 'Oil fluoroscope UV box', 'The source identifies YG1501. Do not assume it is interchangeable with another UV box because some listed values look similar. Confirm the optical, electrical, enclosure and sample-use configuration together.'],
        'oil-fluoroscope-uv-lamp-box' => ['fluoroscope', 'Oil Fluoroscope UV Lamp Box: Selection & Technical Review', 'Oil fluoroscope UV lamp box', 'This sparse record does not establish a complete model-specific specification or validated analysis method. Request the exact model, optical/electrical details and operating documents; do not copy values from another fluoroscope page.'],
        'mud-logging-explosion-proof-monitor' => ['display', 'Mud Logging Explosion-Proof Monitor: Configuration Review', 'Mud logging explosion-proof monitor', 'The source combines power, screen-size and hazardous-area descriptions without a verified order-specific approval package. Confirm the actual display/enclosure configuration, interfaces, nameplate and applicable documents; do not combine all catalogue options into one approved unit.'],
